-- Isolated test fixture: relevant current columns/constraints, not a production dump.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE SCHEMA private; CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth,private,storage,public TO authenticated,anon;
CREATE FUNCTION private.has_role(uuid,text) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE TYPE public.learning_state AS ENUM('new','learning','review','relearning');
CREATE TYPE public.review_rating AS ENUM('again','hard','good','easy');
CREATE TYPE public.flashcard_status AS ENUM('draft','published','archived');
CREATE TYPE public.schedule_status AS ENUM('draft','published','archived');
CREATE TYPE public.media_type AS ENUM('image','document');
CREATE TYPE public.media_placement AS ENUM('question','answer','comment');
CREATE TABLE public.sections(id uuid PRIMARY KEY,name text,is_active boolean NOT NULL DEFAULT true);
CREATE TABLE public.areas(id uuid PRIMARY KEY,name text,is_active boolean NOT NULL DEFAULT true);
CREATE TABLE public.topics(id uuid PRIMARY KEY,area_id uuid REFERENCES public.areas(id),name text,is_active boolean NOT NULL DEFAULT true);
CREATE TABLE public.subtopics(id uuid PRIMARY KEY,topic_id uuid REFERENCES public.topics(id),name text);
CREATE TABLE public.flashcards(id uuid PRIMARY KEY,code text UNIQUE,topic_id uuid REFERENCES public.topics(id),status public.flashcard_status NOT NULL,version integer NOT NULL);
CREATE TABLE public.flashcard_sections(flashcard_id uuid REFERENCES public.flashcards(id),section_id uuid REFERENCES public.sections(id),PRIMARY KEY(flashcard_id,section_id));
CREATE TABLE public.weekly_schedules(id uuid PRIMARY KEY,section_id uuid REFERENCES public.sections(id),status public.schedule_status NOT NULL);
CREATE TABLE public.weekly_schedule_items(id uuid PRIMARY KEY,weekly_schedule_id uuid REFERENCES public.weekly_schedules(id),topic_id uuid REFERENCES public.topics(id),release_at timestamptz NOT NULL);
CREATE TABLE public.flashcard_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),flashcard_id uuid REFERENCES public.flashcards(id),version integer NOT NULL,code text NOT NULL,area_id uuid REFERENCES public.areas(id),topic_id uuid REFERENCES public.topics(id),subtopic_id uuid REFERENCES public.subtopics(id),question text NOT NULL,short_answer text NOT NULL,comment jsonb NOT NULL,reference text NOT NULL,editorial_difficulty text NOT NULL,status public.flashcard_status NOT NULL,changed_by uuid NOT NULL,UNIQUE(flashcard_id,version));
CREATE TABLE public.flashcard_media_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),flashcard_id uuid NOT NULL,card_version integer NOT NULL,media_id uuid NOT NULL,type public.media_type NOT NULL,placement public.media_placement NOT NULL,storage_path text NOT NULL,caption text NOT NULL,alt_text text NOT NULL,display_order integer NOT NULL,is_active boolean NOT NULL,FOREIGN KEY(flashcard_id,card_version) REFERENCES public.flashcard_versions(flashcard_id,version));
CREATE TABLE public.user_flashcard_states(user_id uuid,flashcard_id uuid REFERENCES public.flashcards(id),learning_state public.learning_state NOT NULL DEFAULT 'new',first_seen_at timestamptz,last_reviewed_at timestamptz,next_review_at timestamptz,current_interval numeric NOT NULL DEFAULT 0 CHECK(current_interval>=0),review_count integer NOT NULL DEFAULT 0 CHECK(review_count>=0),lapse_count integer NOT NULL DEFAULT 0 CHECK(lapse_count>=0),fsrs_stability numeric CHECK(fsrs_stability>=0),fsrs_difficulty numeric CHECK(fsrs_difficulty BETWEEN 1 AND 10),fsrs_data jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(fsrs_data)='object'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,flashcard_id));
CREATE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now();RETURN NEW; END $$;
CREATE TRIGGER user_flashcard_states_set_updated_at BEFORE UPDATE ON public.user_flashcard_states FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
GRANT SELECT,INSERT,UPDATE ON public.user_flashcard_states TO authenticated;
CREATE TABLE public.review_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,flashcard_id uuid REFERENCES public.flashcards(id),reviewed_at timestamptz NOT NULL DEFAULT now(),rating public.review_rating NOT NULL,previous_interval numeric NOT NULL DEFAULT 0 CHECK(previous_interval>=0),new_interval numeric NOT NULL CHECK(new_interval>=0),scheduled_next_review timestamptz NOT NULL,card_version_seen integer NOT NULL CHECK(card_version_seen>0),learning_state_before public.learning_state,learning_state_after public.learning_state NOT NULL,fsrs_data jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(fsrs_data)='object'),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(flashcard_id,card_version_seen) REFERENCES public.flashcard_versions(flashcard_id,version));
GRANT SELECT,INSERT ON public.review_events TO authenticated;
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text,name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON storage.objects TO authenticated;
